edges = [(0,1),(1,2),(2,3),(3,4),(4,6),(6,8),(8,9),(9,10),(10,11),(11,5),(5,7)]

def is_bipartite(edges, n):
    adj = [[] for _ in range(n)]
    for u,v in edges:
        adj[u].append(v)
        adj[v].append(u)
    color = [-1]*n
    for i in range(n):
        if color[i]==-1:
            color[i]=0
            stack=[i]
            while stack:
                u=stack.pop()
                for v in adj[u]:
                    if color[v]==-1:
                        color[v]=1-color[u]
                        stack.append(v)
                    elif color[v]==color[u]:
                        return False, (u,v,color)
    return True, None

